window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c5b98b6c55168c37"]={"versions": [{"id": "FIG-c5b98b6c55168c37", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Modellierungsrichtlinie / Taxonomie-Matrix für Namenskonventionen (Naming Consistency Rules) von AUTOSAR-Port-Schnittstellen und Datenelementen.</li>\n<li><strong>Technischer Zweck:</strong> Vereinheitlichung der Semantik und Bezeichner (Keywords/Abkürzungen) in VFB-Schnittstellen (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>ModeSwitchInterface</code>) für die Domäne Fahrwerk (<code>AUTOSAR_EXP_AIChassis</code>). Ziel ist die deterministische Modellierung von Sollwerten/Steuerbefehlen (<em>Command</em>) gegenüber Istwerten/Zustandsrückmeldungen (<em>Feedback</em>) über Funktionsgrenzen hinweg.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert Signale und Software-Elemente über eine 2×2-Klassifikationsmatrix nach Signalart und Kommunikationsrichtung:</p>\n<p class=\"fig-p\">#### 1. Zeile: Kontinuierliche Regel- und Stellgrößen (<code>Controller value, actuator value</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Sollwert / Anforderung):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>Request</code> (Kurzform/Keyword: <code>Req</code>). Standardbegriff für Ziel-/Sollwerte eines Reglers (z. B. <code>BrakeAssistRequest</code>).</li>\n<li><strong>Differenzierung / Arbitrierung:</strong></li>\n<li><code>Reference</code>: Reserviert für arbitrierte Führungsgrößen zur Abgrenzung gegenüber nicht-arbitrierten Einzelanforderungen (<code>Request</code>).</li>\n<li><code>Target</code>: Als Bezeichner zu vermeiden bzw. durch <code>Reference</code> oder <code>Request</code> zu substituieren, um die Signalflussrichtung eindeutig zu kennzeichnen.</li>\n<li>Dynamische Vorgaben (Driver/System-Consign) vs. statische/diagnostische Umschaltungen (<code>RequestMode_xy</code>, z. B. Sportmodus, Abschaltung).</li>\n<li>*<em>Spalte </em>Feedback<em> (Istwert / Sensorwert):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>\"\"</code> (Leer / Basisname ohne Präfix/Suffix).</li>\n<li><strong>Regel:</strong> Keine redundanten Zusätze wie <code>actual</code>, <code>current</code> oder <code>present</code> (z. B. ist <code>velocity</code> per Definition der aktuelle physikalische Istwert). Die Kennzeichnung als Istwert erfolgt ausschließlich im Meta-Modell / Beschreibungstext (<code>DESC</code> im ARXML).</li>\n<li><strong>Ausnahme:</strong> Explizite Kennzeichnung als <code>Target</code>/<code>Current</code> nur in Sonderfällen zulässig (z. B. TPMS / Reifendruckkontrolle).</li>\n</ul>\n<p class=\"fig-p\">#### 2. Zeile: Diskrete Zustände und Flags (<code>Information, Flag</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Aufforderung / Signalisierung):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>Request</code> (<code>Req</code>) / <code>Indication</code> (<code>Indcn</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>Request</code>: Allgemeine funktionale Anforderung / Zustandswechselanforderung (inkl. Quittierungslogik / <code>Confirmation of ...</code>).</li>\n<li><code>Indication</code>: Exklusiv reserviert für Ausgaben an HMI, Kontrollleuchten (Telltales) oder optische/akustische Anzeigen.</li>\n<li>*<em>Spalte </em>Feedback<em> (Zustandsrückmeldung / Betriebsmodus):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>\"\"</code> / <code>Status</code> (<code>Sts</code>) / <code>Mode</code> (<code>Mod</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>Status</code> (<code>Sts</code>): Dynamischer Systemzustand (z. B. <code>active</code>, <code>failure</code>, <code>in_progress</code>, <code>inactive</code>; konkretes Beispiel: <code>Status: Control Active</code>).</li>\n<li><code>Mode</code> (<code>Mod</code>): Diskreter Funktions- oder Abstimmungsmodus (z. B. Fahrwerksabstimmung <code>Suspension</code> $\\rightarrow$ <code>« comfort, sport »</code>; Auswahl, Vorgabe, Parametrierung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Nomenklatur- und Entwurfsrichtlinie bildet das Diagramm keinen direkten Laufzeit-Callgraph ab, erzwingt jedoch einen gerichteten Informationsfluss zwischen Software-Components (SWCs):</p>\n<p class=\"fig-p\">```mermaid</p>\n<p class=\"fig-p\">flowchart LR</p>\n<p class=\"fig-p\">subgraph SENDER [Koordinator / Master / HMI]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">REQ[\"Command / Target<br/>• Request (Req)<br/>• Reference<br/>• Indication (Indcn)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">subgraph RECEIVER [Chassis-Aktuator / Regler / Plant]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">ACT[\"Istwert / Zustand<br/>• BaseName (z.B. velocity)<br/>• Status (Sts)<br/>• Mode (Mod)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">REQ -->|SenderReceiver / ClientServer| RECEIVER</p>\n<p class=\"fig-p\">RECEIVER -->|Feedback / Status| SENDER</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Command-Pfad (Sollwertfluss):</strong></li>\n<li>Asynchrone/Periodische Übertragung via <code>SenderReceiverInterface</code> (z. B. Sollmoment, Bremsanforderung).</li>\n<li>Arbitrierungsstufe: Eingehende Anforderungen (<code><em>Request</code>) werden im Koordinator aggregiert; das Ergebnis wird als Führungsgröße (<code></em>Reference</code>) an unterlagerte Regelungs-SWCs weitergegeben.</li>\n<li><strong>Feedback-Pfad (Istwertfluss):</strong></li>\n<li>Sensorische Rückmeldungen werden ohne Präfixe publiziert (<code>*Interface.velocity</code>).</li>\n<li>Zustandsquittierung (<code><em>Status</code>) und Modus-Rückmeldungen (<code></em>Mode</code>) spiegeln den tatsächlichen Zustand der Regelung wider (Closed-Loop-Entkopplung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Datenmodellierung (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li>Strikte Einhaltung der standardisierten Short-Names (<code>Req</code>, <code>Indcn</code>, <code>Sts</code>, <code>Mod</code>) gemäß AUTOSAR-Abkürzungsverzeichnis für <code>VariableDataPrototype</code>, <code>ArgumentDataPrototype</code> und <code>PortPrototype</code>.</li>\n<li>Verbot von <code>actual_</code> / <code>current_</code> in Signalnamen: Entwickler von Sensor-SWCs müssen reine Physikal-Namen vergeben; Verwechslungssicherheit muss über Port-Richtung (<code>PPortPrototype</code> vs. <code>RPortPrototype</code>) und Signalbeschreibungen (<code>desc</code>) im ARXML realisiert werden.</li>\n<li><strong>Mode Management:</strong></li>\n<li>Modus-Anforderungen dürfen nicht mit Regler-Istzuständen kollidieren: Vorgaben tragen den Suffix/Bestandteil <code>Request</code> bzw. <code>Req</code>, während die aktive Modus-Deklaration über <code>ModeSwitchInterface</code> oder Status-Enums das Keyword <code>Mod</code>/<code>Mode</code> nutzt.</li>\n<li><strong>HMI-Entkopplung:</strong></li>\n<li>Datenelemente mit dem Postfix <code>Indcn</code> (<code>Indication</code>) dürfen ausschließlich von Aktuatoren/Logik in Richtung Anzeige-Treiber bzw. HMI-SWCs gesendet werden; sie dürfen innerhalb der Regelungslogik nicht als funktionale Steuerflags rückgelesen werden.</li>\n</ul>"}, {"id": "FIG-fa36af6f43aee356", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Modellierungsrichtlinie / Taxonomie-Matrix für Namenskonventionen (Naming Consistency Rules) von AUTOSAR-Port-Schnittstellen und Datenelementen.</li>\n<li><strong>Technischer Zweck:</strong> Vereinheitlichung der Semantik und Bezeichner (Keywords/Abkürzungen) in VFB-Schnittstellen (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>ModeSwitchInterface</code>) für die Domäne Fahrwerk (<code>AUTOSAR_EXP_AIChassis</code>). Ziel ist die deterministische Modellierung von Sollwerten/Steuerbefehlen (<em>Command</em>) gegenüber Istwerten/Zustandsrückmeldungen (<em>Feedback</em>) über Funktionsgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert Signale und Software-Elemente über eine 2×2-Klassifikationsmatrix nach Signalart und Kommunikationsrichtung:</p>\n<p class=\"fig-p\">#### 1. Zeile: Kontinuierliche Regel- und Stellgrößen (<code>Controller value, actuator value</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Sollwert / Anforderung):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>Request</code> (Kurzform/Keyword: <code>Req</code>). Standardbegriff für Ziel-/Sollwerte eines Reglers (z. B. <code>BrakeAssistRequest</code>).</li>\n<li><strong>Differenzierung / Arbitrierung:</strong></li>\n<li><code>Reference</code>: Reserviert für arbitrierte Führungsgrößen zur Abgrenzung gegenüber nicht-arbitrierten Einzelanforderungen (<code>Request</code>).</li>\n<li><code>Target</code>: Als Bezeichner zu vermeiden bzw. durch <code>Reference</code> oder <code>Request</code> zu substituieren, um die Signalflussrichtung eindeutig zu kennzeichnen.</li>\n<li>Dynamische Vorgaben (Driver/System-Consign) vs. statische/diagnostische Umschaltungen (<code>RequestMode_xy</code>, z. B. Sportmodus, Abschaltung).</li>\n<li>*<em>Spalte </em>Feedback<em> (Istwert / Sensorwert):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>\"\"</code> (Leer / Basisname ohne Präfix/Suffix).</li>\n<li><strong>Regel:</strong> Keine redundanten Zusätze wie <code>consolidated</code> oder <code>present</code> (z. B. ist <code>velocity</code> per Definition der aktuelle physikalische Istwert). Die Kennzeichnung als konsolidierter Signalwert erfolgt ausschließlich im Meta-Modell / Beschreibungstext (<code>DESC</code> im ARXML).</li>\n<li><strong>Ausnahme:</strong> Explizite Kennzeichnung als <code>target value</code> und <code>current value</code> nur in Sonderfällen zulässig (z. B. TPMS / Reifendruckkontrolle).</li>\n</ul>\n<p class=\"fig-p\">#### 2. Zeile: Diskrete Zustände und Flags (<code>Information, Flag</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Aufforderung / Signalisierung):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>Request</code> (<code>Req</code>) / <code>Indication</code> (<code>Indcn</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>Request</code>: Allgemeine funktionale Anforderung / Zustandswechselanforderung (inkl. Quittierungslogik / <code>Confirmation of ...</code>).</li>\n<li><code>Indication</code>: Exklusiv reserviert für Ausgaben an HMI, Kontrollleuchten (Telltales) oder optische/akustische Anzeigen.</li>\n<li>*<em>Spalte </em>Feedback<em> (Zustandsrückmeldung / Betriebsmodus):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>\"\"</code> / <code>State</code> (<code>St</code>) / <code>Mode</code> (<code>Mod</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>State</code> (<code>St</code>): Dynamischer Systemzustand (z. B. <code>active</code>, <code>failure</code>, <code>in_progress</code>, <code>in(active)</code>; konkretes Beispiel: <code>State: Control Active</code>).</li>\n<li><code>Mode</code> (<code>Mod</code>): Diskreter Funktions- oder Abstimmungsmodus (z. B. Fahrwerksabstimmung <code>Suspension</code> $\\rightarrow$ <code>« comfort, sport »</code>; Auswahl, Vorgabe, Parametrierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Nomenklatur- und Entwurfsrichtlinie bildet das Diagramm keinen direkten Laufzeit-Callgraph ab, erzwingt jedoch einen gerichteten Informationsfluss zwischen Software-Components (SWCs):</p>\n<p class=\"fig-p\">```mermaid</p>\n<p class=\"fig-p\">flowchart LR</p>\n<p class=\"fig-p\">subgraph SENDER [Koordinator / Master / HMI]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">REQ[\"Command / Target<br/>• Request (Req)<br/>• Reference<br/>• Indication (Indcn)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">subgraph RECEIVER [Chassis-Aktuator / Regler / Plant]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">ACT[\"Istwert / Zustand<br/>• BaseName (z.B. velocity)<br/>• State (St)<br/>• Mode (Mod)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">REQ -->|SenderReceiver / ClientServer| RECEIVER</p>\n<p class=\"fig-p\">RECEIVER -->|Feedback / State| SENDER</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Command-Pfad (Sollwertfluss):</strong></li>\n<li>Asynchrone/Periodische Übertragung via <code>SenderReceiverInterface</code> (z. B. Sollmoment, Bremsanforderung).</li>\n<li>Arbitrierungsstufe: Eingehende Anforderungen (<code><em>Request</code>) werden im Koordinator aggregiert; das Ergebnis wird als Führungsgröße (<code></em>Reference</code>) an unterlagerte Regelungs-SWCs weitergegeben.</li>\n<li><strong>Feedback-Pfad (Istwertfluss):</strong></li>\n<li>Sensorische Rückmeldungen werden ohne Präfixe publiziert (<code>*Interface.velocity</code>).</li>\n<li>Zustandsquittierung (<code><em>State</code>) und Modus-Rückmeldungen (<code></em>Mode</code>) spiegeln den tatsächlichen Zustand der Regelung wider (Closed-Loop-Entkopplung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Datenmodellierung (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li>Strikte Einhaltung der standardisierten Short-Names (<code>Req</code>, <code>Indcn</code>, <code>St</code>, <code>Mod</code>) gemäß AUTOSAR-Abkürzungsverzeichnis für <code>VariableDataPrototype</code>, <code>ArgumentDataPrototype</code> und <code>PortPrototype</code> (Verwendung des Keywords <code>St</code> statt <code>Sts</code>).</li>\n<li>Verbot von <code>consolidated_</code> / <code>present_</code> in Signalnamen: Entwickler von Sensor-SWCs müssen reine Physikal-Namen vergeben; Verwechslungssicherheit und Spezifikation als konsolidierter Signalwert müssen über Port-Richtung (<code>PPortPrototype</code> vs. <code>RPortPrototype</code>) und Signalbeschreibungen (<code>desc</code>) im ARXML realisiert werden.</li>\n<li><strong>Mode- und State-Management:</strong></li>\n<li>Modus-Anforderungen dürfen nicht mit Systemzuständen kollidieren: Vorgaben tragen den Suffix/Bestandteil <code>Request</code> bzw. <code>Req</code>, während die aktive Modus-Deklaration über <code>ModeSwitchInterface</code> das Keyword <code>Mod</code>/<code>Mode</code> nutzt und dynamische Systemzustände als <code>State</code> (<code>St</code>) ausgewiesen werden.</li>\n<li><strong>HMI-Entkopplung:</strong></li>\n<li>Datenelemente mit dem Postfix <code>Indcn</code> (<code>Indication</code>) dürfen ausschließlich von Aktuatoren/Logik in Richtung Anzeige-Treiber bzw. HMI-SWCs gesendet werden; sie dürfen innerhalb der Regelungslogik nicht als funktionale Steuerflags rückgelesen werden.</li>\n</ul>"}, {"id": "FIG-addf6713e1dd7359", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Modellierungsrichtlinie / Taxonomie-Matrix für Namenskonventionen (Naming Consistency Rules) von AUTOSAR-Port-Schnittstellen und Datenelementen.</li>\n<li><strong>Technischer Zweck:</strong> Vereinheitlichung der Semantik und Bezeichner (Keywords/Abkürzungen) in VFB-Schnittstellen (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>ModeSwitchInterface</code>) für die Domäne Fahrwerk (<code>AUTOSAR_EXP_AIChassis</code>). Ziel ist die deterministische Modellierung von Sollwerten/Steuerbefehlen (<em>Command</em>) gegenüber Istwerten/Zustandsrückmeldungen (<em>Feedback</em>) über Funktionsgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert Signale und Software-Elemente über eine 2×2-Klassifikationsmatrix nach Signalart und Kommunikationsrichtung:</p>\n<p class=\"fig-p\">#### 1. Zeile: Kontinuierliche Regel- und Stellgrößen (<code>Controller value, actuator value</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Sollwert / Anforderung):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>Request</code> (Kurzform/Keyword: <code>Req</code>). Standardbegriff für Ziel-/Sollwerte eines Reglers (z. B. <code>BrakeAssistRequest</code>).</li>\n<li><strong>Differenzierung / Arbitrierung:</strong></li>\n<li><code>Reference</code>: Reserviert für arbitrierte Führungsgrößen zur Abgrenzung gegenüber nicht-arbitrierten Einzelanforderungen (<code>Request</code>).</li>\n<li><code>Target</code>: Als Bezeichner zu vermeiden bzw. durch <code>Reference</code> oder <code>Request</code> zu substituieren, um die Signalflussrichtung eindeutig zu kennzeichnen.</li>\n<li>Dynamische Vorgaben (Driver/System-Consign) vs. statische/diagnostische Umschaltungen (<code>RequestMode_xy</code>, z. B. Sportmodus, Abschaltung).</li>\n<li>*<em>Spalte </em>Feedback<em> (Istwert / Sensorwert):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>\"\"</code> (Leer / Basisname ohne Präfix/Suffix).</li>\n<li><strong>Regel:</strong> Keine redundanten Zusätze wie <code>consolidated</code> oder <code>present</code> (z. B. ist <code>velocity</code> per Definition der aktuelle physikalische Istwert). Die Kennzeichnung als konsolidierter Signalwert erfolgt ausschließlich im Meta-Modell / Beschreibungstext (<code>DESC</code> im ARXML).</li>\n<li><strong>Ausnahme:</strong> Explizite Kennzeichnung als <code>target value</code> und <code>current value</code> nur in Sonderfällen zulässig (z. B. TPMS / Reifendruckkontrolle).</li>\n</ul>\n<p class=\"fig-p\">#### 2. Zeile: Diskrete Zustände und Flags (<code>Information, Flag</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Aufforderung / Signalisierung):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>Request</code> (<code>Req</code>) / <code>Indication</code> (<code>Indcn</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>Request</code>: Allgemeine funktionale Anforderung / Zustandswechselanforderung (inkl. Quittierungslogik / <code>Confirmation of ...</code>).</li>\n<li><code>Indication</code>: Exklusiv reserviert für Ausgaben an HMI, Kontrollleuchten (Telltales) oder optische/akustische Anzeigen.</li>\n<li>*<em>Spalte </em>Feedback<em> (Zustandsrückmeldung / Betriebsmodus):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>\"\"</code> / <code>State</code> (<code>St</code>) / <code>Mode</code> (<code>Mod</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>State</code> (<code>St</code>): Dynamischer Systemzustand (z. B. <code>active</code>, <code>failure</code>, <code>in_progress</code>, <code>in(active)</code>; konkretes Beispiel: <code>State: Control Active</code>).</li>\n<li><code>Mode</code> (<code>Mod</code>): Diskreter Funktions- oder Abstimmungsmodus (z. B. Fahrwerksabstimmung <code>Suspension</code> $\\rightarrow$ <code>« comfort, sport »</code>; Auswahl, Vorgabe, Parametrierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Nomenklatur- und Entwurfsrichtlinie bildet das Diagramm keinen direkten Laufzeit-Callgraph ab, erzwingt jedoch einen gerichteten Informationsfluss zwischen Software-Components (SWCs):</p>\n<p class=\"fig-p\">```mermaid</p>\n<p class=\"fig-p\">flowchart LR</p>\n<p class=\"fig-p\">subgraph SENDER [Koordinator / Master / HMI]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">REQ[\"Command / Target<br/>• Request (Req)<br/>• Reference<br/>• Indication (Indcn)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">subgraph RECEIVER [Chassis-Aktuator / Regler / Plant]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">ACT[\"Istwert / Zustand<br/>• BaseName (z.B. velocity)<br/>• State (St)<br/>• Mode (Mod)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">REQ -->|SenderReceiver / ClientServer| RECEIVER</p>\n<p class=\"fig-p\">RECEIVER -->|Feedback / State| SENDER</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Command-Pfad (Sollwertfluss):</strong></li>\n<li>Asynchrone/Periodische Übertragung via <code>SenderReceiverInterface</code> (z. B. Sollmoment, Bremsanforderung).</li>\n<li>Arbitrierungsstufe: Eingehende Anforderungen (<code><em>Request</code>) werden im Koordinator aggregiert; das Ergebnis wird als Führungsgröße (<code></em>Reference</code>) an unterlagerte Regelungs-SWCs weitergegeben.</li>\n<li><strong>Feedback-Pfad (Istwertfluss):</strong></li>\n<li>Sensorische Rückmeldungen werden ohne Präfixe publiziert (<code>*Interface.velocity</code>).</li>\n<li>Zustandsquittierung (<code><em>State</code>) und Modus-Rückmeldungen (<code></em>Mode</code>) spiegeln den tatsächlichen Zustand der Regelung wider (Closed-Loop-Entkopplung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Datenmodellierung (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li>Strikte Einhaltung der standardisierten Short-Names (<code>Req</code>, <code>Indcn</code>, <code>St</code>, <code>Mod</code>) gemäß AUTOSAR-Abkürzungsverzeichnis für <code>VariableDataPrototype</code>, <code>ArgumentDataPrototype</code> und <code>PortPrototype</code> (Verwendung des Keywords <code>St</code> statt <code>Sts</code>).</li>\n<li>Verbot von <code>consolidated_</code> / <code>present_</code> in Signalnamen: Entwickler von Sensor-SWCs müssen reine Physikal-Namen vergeben; Verwechslungssicherheit und Spezifikation als konsolidierter Signalwert müssen über Port-Richtung (<code>PPortPrototype</code> vs. <code>RPortPrototype</code>) und Signalbeschreibungen (<code>desc</code>) im ARXML realisiert werden.</li>\n<li><strong>Mode- und State-Management:</strong></li>\n<li>Modus-Anforderungen dürfen nicht mit Systemzuständen kollidieren: Vorgaben tragen den Suffix/Bestandteil <code>Request</code> bzw. <code>Req</code>, während die aktive Modus-Deklaration über <code>ModeSwitchInterface</code> das Keyword <code>Mod</code>/<code>Mode</code> nutzt und dynamische Systemzustände als <code>State</code> (<code>St</code>) ausgewiesen werden.</li>\n<li><strong>HMI-Entkopplung:</strong></li>\n<li>Datenelemente mit dem Postfix <code>Indcn</code> (<code>Indication</code>) dürfen ausschließlich von Aktuatoren/Logik in Richtung Anzeige-Treiber bzw. HMI-SWCs gesendet werden; sie dürfen innerhalb der Regelungslogik nicht als funktionale Steuerflags rückgelesen werden.</li>\n</ul>"}, {"id": "FIG-bbfa7ceee75375ac", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Modellierungsrichtlinie / Taxonomie-Matrix für Namenskonventionen (Naming Consistency Rules) von AUTOSAR-Port-Schnittstellen und Datenelementen.</li>\n<li><strong>Technischer Zweck:</strong> Vereinheitlichung der Semantik und Bezeichner (Keywords/Abkürzungen) in VFB-Schnittstellen (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>, <code>ModeSwitchInterface</code>) für die Domäne Fahrwerk (<code>AUTOSAR_EXP_AIChassis</code>). Ziel ist die deterministische Modellierung von Sollwerten/Steuerbefehlen (<em>Command</em>) gegenüber Istwerten/Zustandsrückmeldungen (<em>Feedback</em>) über Funktionsgrenzen hinweg.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert Signale und Software-Elemente über eine 2×2-Klassifikationsmatrix nach Signalart und Kommunikationsrichtung:</p>\n<p class=\"fig-p\">#### 1. Zeile: Kontinuierliche Regel- und Stellgrößen (<code>Controller value, actuator value</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Sollwert / Anforderung):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>Request</code> (Kurzform/Keyword: <code>Req</code>). Standardbegriff für Ziel-/Sollwerte eines Reglers (z. B. <code>BrakeAssistRequest</code>).</li>\n<li><strong>Differenzierung / Arbitrierung:</strong></li>\n<li><code>Reference</code>: Reserviert für arbitrierte Führungsgrößen zur Abgrenzung gegenüber nicht-arbitrierten Einzelanforderungen (<code>Request</code>).</li>\n<li><code>Target</code>: Als Bezeichner zu vermeiden bzw. durch <code>Reference</code> oder <code>Request</code> zu substituieren, um die Signalflussrichtung eindeutig zu kennzeichnen.</li>\n<li>Dynamische Vorgaben (Driver/System-Consign) vs. statische/diagnostische Umschaltungen (<code>RequestMode_xy</code>, z. B. Sportmodus, Abschaltung).</li>\n<li>*<em>Spalte </em>Feedback<em> (Istwert / Sensorwert):</em>*</li>\n<li><strong>Primär-Identifikator:</strong> <code>\"\"</code> (Leer / Basisname ohne Präfix/Suffix).</li>\n<li><strong>Regel:</strong> Keine redundanten Zusätze wie <code>consolidated</code> oder <code>present</code> (z. B. ist <code>velocity</code> per Definition der aktuelle physikalische Istwert). Die Kennzeichnung als konsolidierter Signalwert erfolgt ausschließlich im Meta-Modell / Beschreibungstext (<code>DESC</code> im ARXML).</li>\n<li><strong>Ausnahme:</strong> Explizite Kennzeichnung als <code>target value</code> und <code>current value</code> nur in Sonderfällen zulässig (z. B. TPMS / Reifendruckkontrolle).</li>\n</ul>\n<p class=\"fig-p\">#### 2. Zeile: Diskrete Zustände und Flags (<code>Information, Flag</code>)</p>\n<ul class=\"fig-list\">\n<li>*<em>Spalte </em>Command<em> (Aufforderung / Signalisierung):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>Request</code> (<code>Req</code>) / <code>Indication</code> (<code>Indcn</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>Request</code>: Allgemeine funktionale Anforderung / Zustandswechselanforderung (inkl. Quittierungslogik / <code>Confirmation of ...</code>).</li>\n<li><code>Indication</code>: Exklusiv reserviert für Ausgaben an HMI, Kontrollleuchten (Telltales) oder optische/akustische Anzeigen.</li>\n<li>*<em>Spalte </em>Feedback<em> (Zustandsrückmeldung / Betriebsmodus):</em>*</li>\n<li><strong>Identifikatoren:</strong> <code>\"\"</code> / <code>State</code> (<code>St</code>) / <code>Mode</code> (<code>Mod</code>).</li>\n<li><strong>Semantische Trennung:</strong></li>\n<li><code>State</code> (<code>St</code>): Dynamischer Systemzustand (z. B. <code>active</code>, <code>failure</code>, <code>in_progress</code>, <code>in(active)</code>; konkretes Beispiel: <code>State: Control Active</code>).</li>\n<li><code>Mode</code> (<code>Mod</code>): Diskreter Funktions- oder Abstimmungsmodus (z. B. Fahrwerksabstimmung <code>Suspension</code> $\\rightarrow$ <code>« comfort, sport »</code>; Auswahl, Vorgabe, Parametrierung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Nomenklatur- und Entwurfsrichtlinie bildet das Diagramm keinen direkten Laufzeit-Callgraph ab, erzwingt jedoch einen gerichteten Informationsfluss zwischen Software-Components (SWCs):</p>\n<p class=\"fig-p\">```mermaid</p>\n<p class=\"fig-p\">flowchart LR</p>\n<p class=\"fig-p\">subgraph SENDER [Koordinator / Master / HMI]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">REQ[\"Command / Target<br/>• Request (Req)<br/>• Reference<br/>• Indication (Indcn)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">subgraph RECEIVER [Chassis-Aktuator / Regler / Plant]</p>\n<p class=\"fig-p\">direction TB</p>\n<p class=\"fig-p\">ACT[\"Istwert / Zustand<br/>• BaseName (z.B. velocity)<br/>• State (St)<br/>• Mode (Mod)\"]</p>\n<p class=\"fig-p\">end</p>\n<p class=\"fig-p\">REQ -->|SenderReceiver / ClientServer| RECEIVER</p>\n<p class=\"fig-p\">RECEIVER -->|Feedback / State| SENDER</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Command-Pfad (Sollwertfluss):</strong></li>\n<li>Asynchrone/Periodische Übertragung via <code>SenderReceiverInterface</code> (z. B. Sollmoment, Bremsanforderung).</li>\n<li>Arbitrierungsstufe: Eingehende Anforderungen (<code><em>Request</code>) werden im Koordinator aggregiert; das Ergebnis wird als Führungsgröße (<code></em>Reference</code>) an unterlagerte Regelungs-SWCs weitergegeben.</li>\n<li><strong>Feedback-Pfad (Istwertfluss):</strong></li>\n<li>Sensorische Rückmeldungen werden ohne Präfixe publiziert (<code>*Interface.velocity</code>).</li>\n<li>Zustandsquittierung (<code><em>State</code>) und Modus-Rückmeldungen (<code></em>Mode</code>) spiegeln den tatsächlichen Zustand der Regelung wider (Closed-Loop-Entkopplung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Datenmodellierung (<code>AUTOSAR_EXP_AIChassis</code>):</strong></li>\n<li>Strikte Einhaltung der standardisierten Short-Names (<code>Req</code>, <code>Indcn</code>, <code>St</code>, <code>Mod</code>) gemäß AUTOSAR-Abkürzungsverzeichnis für <code>VariableDataPrototype</code>, <code>ArgumentDataPrototype</code> und <code>PortPrototype</code> (Verwendung des Keywords <code>St</code> statt <code>Sts</code>).</li>\n<li>Verbot von <code>consolidated_</code> / <code>present_</code> in Signalnamen: Entwickler von Sensor-SWCs müssen reine Physikal-Namen vergeben; Verwechslungssicherheit und Spezifikation als konsolidierter Signalwert müssen über Port-Richtung (<code>PPortPrototype</code> vs. <code>RPortPrototype</code>) und Signalbeschreibungen (<code>desc</code>) im ARXML realisiert werden.</li>\n<li><strong>Mode- und State-Management:</strong></li>\n<li>Modus-Anforderungen dürfen nicht mit Systemzuständen kollidieren: Vorgaben tragen den Suffix/Bestandteil <code>Request</code> bzw. <code>Req</code>, während die aktive Modus-Deklaration über <code>ModeSwitchInterface</code> das Keyword <code>Mod</code>/<code>Mode</code> nutzt und dynamische Systemzustände als <code>State</code> (<code>St</code>) ausgewiesen werden.</li>\n<li><strong>HMI-Entkopplung:</strong></li>\n<li>Datenelemente mit dem Postfix <code>Indcn</code> (<code>Indication</code>) dürfen ausschließlich von Aktuatoren/Logik in Richtung Anzeige-Treiber bzw. HMI-SWCs gesendet werden; sie dürfen innerhalb der Regelungslogik nicht als funktionale Steuerflags rückgelesen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-c5b98b6c55168c37", "to": "FIG-fa36af6f43aee356", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Information, Flag / Feedback</code>: Kategoriebezeichner von <code>Status</code> zu <code>State</code> geändert (<code>“.....“ / Status / Mode</code> → <code>“.....“ / State / Mode</code>), zugehöriges Keyword von <code>Sts/Mod</code> auf <code>St/Mod</code> angepasst (<code>Sts</code> → <code>St</code>) sowie Beispiel im Text von <code>Status: Control Active</code> auf <code>State: Control Active</code> aktualisiert.</li>\n<li><code>Controller value, actuator value / Feedback</code>: Signalzusatz-Beispiele von <code>actual, current, present, ..</code> auf <code>consolidated, present, ..</code> geändert und Beschreibungsanforderung von <code>actual/current value of the signal</code> auf <code>consolidated value of the signal</code> angepasst.</li>\n</ul>"}, {"from": "FIG-fa36af6f43aee356", "to": "FIG-addf6713e1dd7359", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-addf6713e1dd7359", "to": "FIG-bbfa7ceee75375ac", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
